  {
    titulo = "Ventormenta", min = 10, max = 11,
    entrenar = "En Ventormenta tus instructores de paladín están en la Catedral de la Luz: Lord Grisillo Quiebrasombras y Arthur el Leal. En Forjaz, en el noroeste de la ciudad: Brandur Martiyerro, Valgar Forjalta y Beldruk Ceñomaldito. Al 12 aprende Golpe sagrado (rango 2) y Bendición de poderío (rango 2). Talento: Fuerza divina hasta el 14.",
    equipo = "Las mazas de dos manos ya las sabes usar; en Forjaz, Buliwyf Petramano enseña también hachas de dos manos. En la subasta busca una maza de dos manos con Fuerza o Aguante: es tu mayor mejora de daño.",
    profesion = "Minería y Desuello a 50: rango oficial con Gelman Petramano y Maris Granger en Ventormenta, o con Geofram Dedorroca y Balthus Cazarrocas en Forjaz. Primeros auxilios con Shaina Fuller, en la Plaza de la Catedral: <Venda de lino>. Guarda 10 <Paño de lino> para tu misión de clase del 20.",
    pasos = {
      { t = "Sigue el camino al norte hasta Ventormenta. En el Distrito de Mercaderes activa el vuelo con Dungar Tragolargo y entrega [Un envío para Ventormenta] a Morgan Mortero.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 71.3, y = 72.2, n = "Dungar Tragolargo", npc = 352 }, { m = 1453, z = "Ciudad de Ventormenta", x = 63.2, y = 74.4, n = "Entregar: Un envío para Ventormenta (Morgan Mortero)", q = 61, a = "T" } } },
      { t = "Nivel 10: si no entrenaste en Villadorada, hazlo con Lord Grisillo Quiebrasombras en la Catedral de la Luz: Sello de rectitud (rango 2), Aura de devoción (rango 2) e Imposición de manos. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 48.4, y = 50.2, n = "Lord Grisillo Quiebrasombras", npc = 928 } }, comprobar = { hechizos = { 20287 } } },
      { t = "Con 50 de desuello, aprende el rango oficial con Maris Granger, en el Casco Antiguo; con 50 de minería, con Gelman Petramano, en el Distrito de los Enanos. En la Plaza de la Catedral, Shaina Fuller enseña Primeros auxilios.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 72.1, y = 62.2, n = "Maris Granger", npc = 1292 }, { m = 1453, z = "Ciudad de Ventormenta", x = 53.0, y = 44.7, n = "Shaina Fuller", npc = 2327 }, { m = 1453, z = "Ciudad de Ventormenta", x = 59.2, y = 37.8, n = "Gelman Petramano", npc = 5513 } }, comprobar = { oficios = { 129 } } },
    },
