      { t = "En el Distrito de los Enanos coge el Tranvía Subterráneo a Forjaz y activa el vuelo con Gryth Thurden en la Gran Herrería: lo usarás para venir a entrenar.", wp = { { m = 1455, z = "Forjaz", x = 55.5, y = 47.7, n = "Gryth Thurden", npc = 1573 } }, comprobar = { vuelo = "Forjaz" } },
