  {
    titulo = "Loch Modan", min = 15, max = 18,
    entrenar = "Talentos: 10-14 Fuerza divina y 15-19 Sellos mejorados (más daño con tus sellos y sentencias). Al 12: Golpe sagrado (rango 2) y Bendición de poderío (rango 2); al 14, Luz Sagrada (rango 3); al 18, Sello de rectitud (rango 3) y Protección divina (rango 2). Vuela a Forjaz desde Thelsamar para entrenar.",
    equipo = "Las misiones del lago dan armas y piezas de cuero y malla. Mira en la subasta de Forjaz un arma de dos manos 'del oso' o 'del tigre'. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Cobre y estaño en las colinas del lago: con 65 de minería ya puedes minar estaño. Desuello: osos, jabalíes y arañas. Primeros auxilios: <Venda de lino pesado> y, con lana, <Venda de lana>.",
    pasos = {
      { t = "En el puesto de control del sur acepta [En defensa de las tierras del rey] y [La amenaza trogg]. Mata troggs Rompepiedras al este del puesto y entrégalas.", wp = { { m = 1432, z = "Loch Modan", x = 22.1, y = 73.1, n = "Recoger: En defensa de las tierras del rey (Montaraz Pedernal)", q = 224, a = "A" }, { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Recoger: La amenaza trogg (Capitán Rugelfuss)", q = 267, a = "A" }, { m = 1432, z = "Loch Modan", x = 32.4, y = 75.0, n = "Objetivo: En defensa de las tierras del rey", q = 224, a = "C" }, { m = 1432, z = "Loch Modan", x = 32.3, y = 75.3, n = "Objetivo: La amenaza trogg", q = 267, a = "C" }, { m = 1432, z = "Loch Modan", x = 22.1, y = 73.1, n = "Entregar: En defensa de las tierras del rey (Montaraz Pedernal)", q = 224, a = "T" }, { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Entregar: La amenaza trogg (Capitán Rugelfuss)", q = 267, a = "T" } } },
      { t = "Thelsamar: piedra de hogar en la posada, activa el vuelo con Thorgrum Borrelson y acepta [Mata ratas] y [Morcillas de Thelsamar].", wp = { { m = 1432, z = "Loch Modan", x = 35.5, y = 48.4, n = "Tabernero Hogartufa", npc = 6734 }, { m = 1432, z = "Loch Modan", x = 33.9, y = 51.0, n = "Thorgrum Borrelson", npc = 1572 }, { m = 1432, z = "Loch Modan", x = 32.6, y = 49.7, n = "Recoger: Mata ratas (Montaraz Kadrell)", q = 416, a = "A" }, { m = 1432, z = "Loch Modan", x = 34.8, y = 49.3, n = "Recoger: Morcillas de Thelsamar (Vidra Hogartufa)", q = 418, a = "A" } } },
