  {
    titulo = "Costa Oscura", min = 18, max = 20,
    entrenar = "En la Costa Oscura no hay instructor para ti: al 20 vuelves a Ventormenta en grifo desde Menethil.",
    equipo = "El camino de Loch Modan a Menethil cruza Los Humedales, con raptores y cocodrilos de nivel 20-25: no te salgas de él. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello y Minería: osos, acechalunas y cobre y estaño por toda la costa. Primeros auxilios: <Paño de lana> para <Venda de lana>.",
    pasos = {
      { t = "Desde Thelsamar (vuela allí si estás en Forjaz) sigue el camino del norte hasta Dun Algaz y cruza a Los Humedales. Sigue el camino hasta el Puerto de Menethil, al oeste, y activa el vuelo con Shellei Brondir.", wp = { { m = 1437, z = "Los Humedales", x = 9.5, y = 59.7, n = "Shellei Brondir", npc = 1571 } }, comprobar = { vuelo = "Menethil" } },
      { t = "En el muelle de Menethil coge el barco a Auberdine (Costa Oscura). Activa el vuelo con Caylais Plumalunar y acepta [Tierras infestadas] (Tharnariun Espinarbolado), [La cueva de los champiñones] (Barithras Sombraluna), [La torre de Althalaxx] (Centinela Elissa Brisa Estelar), [Un amor eterno] (Cerellean Zarpablanca), [Profundo océano, mar inmenso] (Gorbold Mano de Acero) y [Rico marisco] (Gubber Blump).", wp = { { m = 1439, z = "Costa Oscura", x = 36.3, y = 45.6, n = "Caylais Plumalunar", npc = 3841 }, { m = 1439, z = "Costa Oscura", x = 38.8, y = 43.4, n = "Recoger: Tierras infestadas (Tharnariun Espinarbolado)", q = 2118, a = "A" }, { m = 1439, z = "Costa Oscura", x = 37.3, y = 43.6, n = "Recoger: La cueva de los champiñones (Barithras Sombraluna)", q = 947, a = "A" }, { m = 1439, z = "Costa Oscura", x = 39.0, y = 43.5, n = "Recoger: La torre de Althalaxx (Centinela Elissa Brisa Estelar)", q = 965, a = "A" }, { m = 1439, z = "Costa Oscura", x = 35.7, y = 43.7, n = "Recoger: Un amor eterno (Cerellean Zarpablanca)", q = 963, a = "A" }, { m = 1439, z = "Costa Oscura", x = 38.1, y = 41.2, n = "Recoger: Profundo océano, mar inmenso (Gorbold Mano de Acero)", q = 982, a = "A" }, { m = 1439, z = "Costa Oscura", x = 36.1, y = 44.9, n = "Recoger: Rico marisco (Gubber Blump)", q = 1138, a = "A" } } },
      { t = "Al norte de Auberdine, en el barco hundido de la costa, abre los dos arcones de [Profundo océano, mar inmenso]: están bajo el agua. En la playa, mata corremareas escamados y correarrecifes para [Rico marisco].", wp = { { m = 1439, z = "Costa Oscura", x = 38.9, y = 28.1, n = "Objetivo: Profundo océano, mar inmenso", q = 982, a = "C" }, { m = 1439, z = "Costa Oscura", x = 49.7, y = 20.8, n = "Objetivo: Rico marisco", q = 1138, a = "C" } } },
      { t = "Al norte de Bashal'Aran, usa la trampa de [Tierras infestadas] con un oso Cardo rabioso: te seguirá mientras vuelves a Auberdine. Entrégala a Tharnariun Espinarbolado y acepta [La limpieza de la infección].", wp = { { m = 1439, z = "Costa Oscura", x = 49.0, y = 29.8, n = "Objetivo: Tierras infestadas", q = 2118, a = "C" }, { m = 1439, z = "Costa Oscura", x = 38.8, y = 43.4, n = "Entregar: Tierras infestadas (Tharnariun Espinarbolado)", q = 2118, a = "T" }, { m = 1439, z = "Costa Oscura", x = 38.8, y = 43.4, n = "Recoger: La limpieza de la infección (Tharnariun Espinarbolado)", q = 2138, a = "A" } } },
      { t = "Torre de Althalaxx, al nordeste: entrega [La torre de Althalaxx] a Balthule Golpesombra y acepta [La torre de Althalaxx]: los fanáticos de la Facción Oscura de la torre sueltan los pliegos. Entrégala. Por el camino, mata osos cardo rabiosos para [La limpieza de la infección].", wp = { { m = 1439, z = "Costa Oscura", x = 55.0, y = 24.9, n = "Entregar: La torre de Althalaxx (Balthule Golpesombra)", q = 965, a = "T" }, { m = 1439, z = "Costa Oscura", x = 55.0, y = 24.9, n = "Recoger: La torre de Althalaxx (Balthule Golpesombra)", q = 966, a = "A" }, { m = 1439, z = "Costa Oscura", x = 56.3, y = 26.7, n = "Objetivo: La torre de Althalaxx", q = 966, a = "C" }, { m = 1439, z = "Costa Oscura", x = 55.0, y = 24.9, n = "Entregar: La torre de Althalaxx (Balthule Golpesombra)", q = 966, a = "T" }, { m = 1439, z = "Costa Oscura", x = 49.0, y = 29.8, n = "Objetivo: La limpieza de la infección", q = 2138, a = "C" } } },
      { t = "Al sur de la torre, en la cueva, recoge níscalos y almetes de la muerte para [La cueva de los champiñones].", wp = { { m = 1439, z = "Costa Oscura", x = 55.7, y = 35.1, n = "Objetivo: La cueva de los champiñones", q = 947, a = "C" } } },
