  {
    titulo = "Vuelta a Ventormenta", min = 20, max = 20,
    entrenar = "Nivel 20 = gran entrenamiento en Ventormenta con Lord Grisillo Quiebrasombras, en la Catedral de la Luz: Consagración (daño Sagrado a todos los que tienes cerca: tu mejor golpe contra varios), Exorcismo (solo contra no-muertos y demonios), Destello de Luz (cura rápida), Golpe sagrado (rango 3) y Aura de devoción (rango 3). Talento 20: Conducto sagrado. En la Catedral, Duthorian Rall sigue tu misión de clase: acaba con Redención (resucitar a otros jugadores).",
    equipo = "Objetivo: completar la cadena [La hermandad de los Defias] hasta Las Minas de la Muerte. La última parte da <Bastón de Páramos de Poniente>. En la mazmorra, Don Mamporro suelta <Martillo poderoso de acometida>: una gran maza de dos manos. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello: lobos, jabalíes y buitres de Poniente dan <Cuero ligero> y <Cuero medio>. Minería: cobre y estaño en las colinas. Primeros auxilios: <Venda de lana>. Lleva 10 <Paño de lino> para tu misión de clase del 20.",
    pasos = {
      { t = "Nivel 20: vuela a Ventormenta y entrena con Lord Grisillo Quiebrasombras en la Catedral de la Luz: Consagración, Exorcismo, Destello de Luz, Golpe sagrado (rango 3) y Aura de devoción (rango 3). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 48.4, y = 50.2, n = "Lord Grisillo Quiebrasombras", npc = 928 } }, comprobar = { hechizos = { 26573 } } },
      { t = "Misión de clase: en la Catedral, entrega [Libro de la Divinidad] a Duthorian Rall y abre el <Escrito sobre Divinidad> que te da: empieza la parte siguiente, que le devuelves a él mismo. Acepta la tercera parte.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 50.5, y = 47.5, n = "Entregar: Libro de la Divinidad (Duthorian Rall)", q = 3681, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 50.5, y = 47.5, n = "Abre el Escrito sobre Divinidad", q = 1642, a = "A" }, { m = 1453, z = "Ciudad de Ventormenta", x = 50.5, y = 47.5, n = "Entregar: El Libro de la Divinidad (Duthorian Rall)", q = 1642, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 50.5, y = 47.5, n = "Recoger: El Libro de la Divinidad (Duthorian Rall)", q = 1643, a = "A" } } },
      { t = "Busca a Stephanie Turner en el Distrito de Mercaderes (la flecha te lleva) y habla con ella: te pide 10 <Paño de lino>. Dáselos y acepta la parte siguiente, que se entrega a Duthorian Rall.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 63.8, y = 72.2, n = "Entregar: El Libro de la Divinidad (Stephanie Turner)", q = 1643, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 63.8, y = 72.2, n = "Recoger: El Libro de la Divinidad (Stephanie Turner)", q = 1644, a = "A" }, { m = 1453, z = "Ciudad de Ventormenta", x = 63.8, y = 72.2, n = "Entregar: El Libro de la Divinidad (Stephanie Turner)", q = 1644, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 63.8, y = 72.2, n = "Recoger: Escrito sobre divinidad (Stephanie Turner)", q = 1780, a = "A" } } },
      { t = "Vuelve a la Catedral con Duthorian Rall y acepta la parte siguiente: lleva el <Símbolo de Vida> a Gazin Tenorm, también en la Catedral. Te da la parte de Henze Faulk, que harás al nordeste de Elwynn, de camino a Crestagrana.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 50.5, y = 47.5, n = "Entregar: Escrito sobre divinidad (Duthorian Rall)", q = 1780, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 50.5, y = 47.5, n = "Recoger: El Libro de la Divinidad (Duthorian Rall)", q = 1781, a = "A" }, { m = 1453, z = "Ciudad de Ventormenta", x = 49.5, y = 45.0, n = "Entregar: El Libro de la Divinidad (Gazin Tenorm)", q = 1781, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 49.5, y = 45.0, n = "Recoger: Escrito sobre divinidad (Gazin Tenorm)", q = 1786, a = "A" } } },
    },
  },
  {
    titulo = "Montañas Crestagrana", min = 20, max = 23,
    entrenar = "Pelea así: Sello de rectitud puesto, Sentencia cada vez que esté lista y Golpe sagrado; contra varios, Consagración. Al 22: Bendición de poderío (rango 3) y Luz Sagrada (rango 4); al 24, Martillo de justicia (rango 2). Talentos 22-26: Reprensión > Bendición (tus hechizos instantáneos cuestan menos maná).",
    equipo = "Busca grupo para Las Minas de la Muerte (entrada en Arroyo de la Luna, Poniente): Don Mamporro suelta <Martillo poderoso de acometida>. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello 75-150: <Cuero medio> de cóndores, jabalíes y arañas. Minería: estaño y plata en las colinas de Crestagrana.",
    pasos = {
      { t = "Misión de clase: sal de Ventormenta hacia el este por Elwynn hasta el lago del nordeste. Usa el <Símbolo de Vida> con Henze Faulk, junto a la orilla, para resucitarlo, habla con él y acepta la parte siguiente: los zahoríes bribones Defias del lago sueltan el <Pergamino Defias>. Guárdalo: lo entregarás en Ventormenta al 22.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 72.6, y = 51.4, n = "Objetivo: Escrito sobre divinidad", q = 1786, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 72.6, y = 51.4, n = "Entregar: Escrito sobre divinidad (Henze Faulk)", q = 1786, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 72.6, y = 51.4, n = "Recoger: Libro de la Divinidad (Henze Faulk)", q = 1787, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 74.1, y = 51.5, n = "Objetivo: Libro de la Divinidad", q = 1787, a = "C" } } },
      { t = "Sigue al sureste por Elwynn hasta Villa del Lago. Acepta [Gnolls invasores] en la entrada oeste de la zona; en Villa del Lago activa el vuelo con Ariena Tempespluma, entrega [La hermandad de los Defias] y sigue con [La hermandad de los Defias].", wp = { { m = 1433, z = "Montañas Crestagrana", x = 10.4, y = 71.3, n = "Recoger: Gnolls invasores (Guardia Parker)", q = 244, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 25.5, y = 59.4, n = "Ariena Tempespluma", npc = 931 }, { m = 1433, z = "Montañas Crestagrana", x = 21.4, y = 45.4, n = "Entregar: La hermandad de los Defias (Wiley el Negro)", q = 65, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 21.4, y = 45.4, n = "Recoger: La hermandad de los Defias (Wiley el Negro)", q = 132, a = "A" } } },
      { t = "Entrega [Gnolls invasores] a Ayudante de alguacil Feldon y acepta [Evaluar la amenaza]: mata gnolls y furtivos al sur.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 25.6, y = 60.0, n = "Entregar: Gnolls invasores (Ayudante de alguacil Feldon)", q = 244, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 25.6, y = 60.0, n = "Recoger: Evaluar la amenaza (Ayudante de alguacil Feldon)", q = 246, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 26.6, y = 82.6, n = "Objetivo: Evaluar la amenaza", q = 246, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 25.6, y = 60.0, n = "Entregar: Evaluar la amenaza (Ayudante de alguacil Feldon)", q = 246, a = "T" } } },
      { t = "[El collar de Hilary]: busca el collar en el fondo del lago. [Las herramientas perdidas]: la caja de herramientas también está en el lago.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 24.2, y = 53.6, n = "Recoger: El collar de Hilary (Shawn)", q = 3741, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 24.0, y = 54.1, n = "Objetivo: El collar de Hilary", q = 3741, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 24.1, y = 53.6, n = "Entregar: El collar de Hilary (Hilary)", q = 3741, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 27.1, y = 48.6, n = "Recoger: Las herramientas perdidas (Supervisor Olento)", q = 125, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 36.4, y = 54.7, n = "Objetivo: Las herramientas perdidas", q = 125, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 27.1, y = 48.6, n = "Entregar: Las herramientas perdidas (Supervisor Olento)", q = 125, a = "T" } } },
      { t = "[Cazadores furtivos] y [Pescado a la venta] (Maestro de embarcadero Baren, en el muelle): murlocs al este del lago.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 22.6, y = 47.4, n = "Recoger: Cazadores furtivos (Maestro de embarcadero Baren)", q = 150, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 22.6, y = 47.4, n = "Recoger: Pescado a la venta (Maestro de embarcadero Baren)", q = 127, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 36.5, y = 50.0, n = "Objetivo: Cazadores furtivos", q = 150, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 36.5, y = 50.0, n = "Objetivo: Pescado a la venta", q = 127, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 22.6, y = 47.4, n = "Entregar: Cazadores furtivos (Maestro de embarcadero Baren)", q = 150, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 22.6, y = 47.4, n = "Entregar: Pescado a la venta (Maestro de embarcadero Baren)", q = 127, a = "T" } } },
      { t = "[Estofado de Crestagrana]: cóndores, jabalíes y arañas por toda la zona.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 17.6, y = 43.8, n = "Recoger: Estofado de Crestagrana (Chef Breanna)", q = 92, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 48.4, y = 41.8, n = "Objetivo: Estofado de Crestagrana", q = 92, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 17.6, y = 43.8, n = "Entregar: Estofado de Crestagrana (Chef Breanna)", q = 92, a = "T" } } },
