  {
    titulo = "Las Mil Agujas", min = 30, max = 32,
    entrenar = "Al 32 coge el talento Sello de orden: con un arma de dos manos lenta pega más que Sello de rectitud, así que cámbialo por él. Sus rangos los vende el instructor desde el 30. Talentos: 33-34 Persecución de la justicia (corres más) y 35-36 Vindicación. Instructor en Kalimdor: Hermano Karman, en Theramore.",
    equipo = "Las misiones de El Desierto de Sal dan buenas recompensas de malla y cuero. Las placas llegan al 40. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello 150+: <Cuero pesado> de las bestias de Las Mil Agujas. Minería 125-175: hierro y oro en las colinas de Las Mil Agujas y de Tanaris.",
    pasos = {
      { t = "Vuela a Menethil y coge el barco a Theramore (Marjal Revolcafango). Activa el vuelo con Baldruc: muy cerca está tu instructor, Hermano Karman.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 67.5, y = 51.3, n = "Baldruc", npc = 4321 }, { m = 1445, z = "Marjal Revolcafango", x = 67.4, y = 47.4, n = "Hermano Karman", npc = 8140 } }, comprobar = { vuelo = "Theramore" } },
      { t = "Desde Theramore ve al oeste por el camino hasta Los Baldíos, baja al sur hasta el Gran Elevador y sigue al este por Las Mil Agujas hasta El Desierto de Sal.", wp = { { m = 1441, z = "Las Mil Agujas", x = 78.0, y = 77.0, n = "El Desierto de Sal" } }, comprobar = { llegar = 1441 } },
      { t = "Acepta [Veneno de escórpidos salados], [Caparazones endurecidos], [Menos peso], [Piezas de coches cohete] y [Un bache en la carretera].", wp = { { m = 1441, z = "Las Mil Agujas", x = 78.1, y = 77.1, n = "Recoger: Veneno de escórpidos salados (Fizzle Pernolatón)", q = 1104, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 78.1, y = 77.1, n = "Recoger: Caparazones endurecidos (Wizzle Pernolatón)", q = 1105, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 80.2, y = 75.9, n = "Recoger: Menos peso (Pozík)", q = 1176, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 77.8, y = 77.3, n = "Recoger: Piezas de coches cohete (Kravel Karbarbán)", q = 1110, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 81.6, y = 78.0, n = "Recoger: Un bache en la carretera (Maestro rastreador Zherin)", q = 1175, a = "A" } } },
      { t = "Escórpidos, tortugas, buitres y basiliscos alrededor de la pista; las piezas de coche caen de todo.", wp = { { m = 1441, z = "Las Mil Agujas", x = 73.3, y = 71.0, n = "Objetivo: Veneno de escórpidos salados", q = 1104, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 81.6, y = 55.2, n = "Objetivo: Caparazones endurecidos", q = 1105, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 87.9, y = 65.4, n = "Objetivo: Menos peso", q = 1176, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 79.2, y = 87.1, n = "Objetivo: Piezas de coches cohete", q = 1110, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 78.3, y = 88.0, n = "Objetivo: Un bache en la carretera", q = 1175, a = "C" } } },
      { t = "Entrega todo en la pista.", wp = { { m = 1441, z = "Las Mil Agujas", x = 78.1, y = 77.1, n = "Entregar: Veneno de escórpidos salados (Fizzle Pernolatón)", q = 1104, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 78.1, y = 77.1, n = "Entregar: Caparazones endurecidos (Wizzle Pernolatón)", q = 1105, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 80.2, y = 75.9, n = "Entregar: Menos peso (Pozík)", q = 1176, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 77.8, y = 77.3, n = "Entregar: Piezas de coches cohete (Kravel Karbarbán)", q = 1110, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 81.6, y = 78.0, n = "Entregar: Un bache en la carretera (Maestro rastreador Zherin)", q = 1175, a = "T" } } },
      { t = "Baja al sur hasta Gadgetzan (Tanaris) y activa el vuelo con Bera Rocamartillo: volverás al 42.", wp = { { m = 1446, z = "Tanaris", x = 51.0, y = 29.3, n = "Bera Rocamartillo", npc = 7823 } }, comprobar = { vuelo = "Gadgetzan" } },
